"""`@generated`: the database computes the column; the engine refuses a write that names it, before SQL."""

import os
import re

import pytest

import monorm
from monorm import _native

SOURCE = """
model Line {
  id       Int @id
  quantity Int
  price    Int
  total    Int @generated(quantity * price)
  @@map("generated_py_lines")
}
"""
URL = os.environ.get("ORM_TEST_DATABASE_URL", "postgres://postgres:postgres@localhost/orm_test")
WANTED = "Line.total is generated by the database"


def _open(dialect):
    source = SOURCE if dialect == "postgres" else 'datasource db { provider = "sqlite" }\n' + SOURCE
    registry = monorm.Registry()
    Line = monorm.loads(source, registry=registry)["Line"]
    return Line, registry, "sqlite://:memory:" if dialect == "sqlite" else URL


@pytest.mark.parametrize("dialect", ["sqlite", "postgres"])
async def test_insert_returns_the_generated_value_and_every_write_refuses_it(dialect):
    Line, registry, url = _open(dialect)
    db = await monorm.connect(url, registry=registry, default=False)
    await db.create_tables()
    try:
        one = await Line.objects.using(db).insert(id=1, quantity=3, price=4)
        assert one.total == 12
        many = await Line.objects.using(db).insert_many(
            [{"id": 2, "quantity": 5, "price": 6}, {"id": 3, "quantity": 1, "price": 1}]
        ).returning()
        assert [r.total for r in many] == [30, 1]
        # A changed input moves the generated value, and a read sees it.
        await Line.objects.using(db).filter(Line.id == 1).update(quantity=10)
        assert (await Line.objects.using(db).get(Line.id == 1)).total == 40
        for write in (
            lambda: Line.objects.using(db).insert(id=9, quantity=1, price=1, total=1),
            lambda: Line.objects.using(db).insert_many([{"id": 9, "quantity": 1, "price": 1, "total": 1}]),
            lambda: Line.objects.using(db).filter(Line.id == 1).update(total=1),
            lambda: Line.objects.using(db).update_many([{"id": 1, "total": 1}]),
            lambda: Line.objects.using(db).insert(id=1, quantity=1, price=1).on_conflict(Line.id, update=True, update_fields=[Line.total]),
            lambda: Line.objects.using(db).insert(id=1, quantity=1, price=1).on_conflict(Line.id, update=True, update_values={"total": 1}),
        ):
            with pytest.raises(monorm.QueryError, match=WANTED):
                await write()
        assert (await Line.objects.using(db).get(Line.id == 1)).total == 40
    finally:
        await db.drop_tables()
        await db.close()


@pytest.mark.parametrize("dialect", ["sqlite", "postgres"])
async def test_a_unique_generated_field_is_a_conflict_target(dialect):
    unique = SOURCE.replace("total    Int @generated", "total    Int @unique @generated")
    source = unique if dialect == "postgres" else 'datasource db { provider = "sqlite" }\n' + unique
    registry = monorm.Registry()
    Line = monorm.loads(source, registry=registry)["Line"]
    db = await monorm.connect("sqlite://:memory:" if dialect == "sqlite" else URL, registry=registry, default=False)
    await db.create_tables()
    try:
        await Line.objects.using(db).insert(id=1, quantity=3, price=4)
        # The same total (12) conflicts on the generated column, and the row is skipped.
        await Line.objects.using(db).insert(id=2, quantity=2, price=6).on_conflict(Line.total, update=False)
        assert [r.id for r in await Line.objects.using(db).order_by(Line.id)] == [1]
    finally:
        await db.drop_tables()
        await db.close()


async def test_a_virtual_generated_column_reads_on_sqlite():
    registry = monorm.Registry()
    source = 'datasource db { provider = "sqlite" }\n' + SOURCE.replace("(quantity * price)", "(quantity * price, stored: false)")
    Line = monorm.loads(source, registry=registry)["Line"]
    db = await monorm.connect("sqlite://:memory:", registry=registry, default=False)
    await db.create_tables()
    try:
        assert (await Line.objects.using(db).insert(id=1, quantity=2, price=7)).total == 14
    finally:
        await db.close()


async def test_a_virtual_generated_column_reads_on_postgres():
    registry = monorm.Registry()
    Line = monorm.loads(SOURCE.replace("(quantity * price)", "(quantity * price, stored: false)"), registry=registry)["Line"]
    db = await monorm.connect(URL, registry=registry, default=False)
    try:
        if int((await db._fetch_text("SHOW server_version_num"))[0][0]) < 180000:
            pytest.skip("VIRTUAL generated columns need PostgreSQL 18")
        await db.create_tables()
        assert (await Line.objects.using(db).insert(id=1, quantity=2, price=7)).total == 14
        with pytest.raises(monorm.QueryError, match=WANTED):
            await Line.objects.using(db).filter(Line.id == 1).update(total=1)
    finally:
        await db.drop_tables()
        await db.close()


def test_the_insert_and_update_types_leave_out_the_generated_field(tmp_path):
    schema = tmp_path / "schema.prisma"
    schema.write_text(SOURCE)
    module, stub = _native.generate_python(str(schema))
    text = module + stub
    for shape in ("LineInsert", "LineUpdate", "LineUpdateRow"):
        block = re.search(rf"class {shape}\(.*?(?=\nclass |\Z)", text, re.S)
        assert block, shape
        assert "    quantity:" in block.group(0) and "    total:" not in block.group(0), shape
    row = re.search(r"class Line\(.*?(?=\nclass |\Z)", text, re.S)
    assert row and "    total:" in row.group(0)
